Q: Font Family Selection With Google Charts? A: <p>I did it like this:<br />
1. Have you font imported into google sheets</p>
<p>2. Run this script in app script (remove what you do not need or add something extra):</p>
<pre><code>function updateChartToGeorama() {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  var charts = sheet.getCharts();

  if (charts.length === 0) {
    Logger.log(&quot;No charts found on this sheet.&quot;);
    return;
  }

  var chart = charts[0];
  var updatedChart = chart.modify()
    .setOption('fontName', '&lt;Your_font&gt;')
    .setOption('titleTextStyle.fontName', '&lt;Your_font&gt;')
    .setOption('legend.textStyle.fontName', '&lt;Your_font&gt;')
    .setOption('hAxis.textStyle.fontName', '&lt;Your_font&gt;')
    .setOption('vAxis.textStyle.fontName', '&lt;Your_font&gt;')
    // Main gridlines light gray
    .setOption('hAxis.gridlines.color', '#CCCCCC')
    .setOption('vAxis.gridlines.color', '#CCCCCC')
    // Minor gridlines invisible
    .setOption('hAxis.minorGridlines.color', '#FFFFFF')
    .setOption('vAxis.minorGridlines.color', '#FFFFFF')
    // Baseline
    .setOption('hAxis.baselineColor', '#CCCCCC')
    .setOption('vAxis.baselineColor', '#CCCCCC')
    // Preserve your series colors or change it
    .setOption('series.0.color', '#0005E2')  
    .setOption('series.1.color', '#FF0D00')  
    .setOption('series.2.color', '#020F44')  
    .setOption('series.3.color', '#700F0A')  
    .setOption('series.4.color', '#E03031')  
    .setOption('series.5.color', '#000B07')  
    .build();

  sheet.updateChart(updatedChart);
}
</code></pre>
